void Solver::rephase() {
    rephases = 0;
    threshold *= 0.85;  // Slightly more aggressive reduction to trigger rephasing earlier
    rephase_limit += 8192;

    // Update saved phases based on current trail assignments
    for (int i = 1; i <= vars; i++) {
        if (value[i] != 0) {
            saved[i] = value[i];  // Save current assignment as preferred phase
        }
    }
}
